def items(project):
    """項目の一覧を位置の順に全部読む。返り値: {"status": "ok", "project_id", "items": [...], "problems": [...], "rate_limit"} か
    {"status": "error", ...} (最初のページが読めないとき)。続きのページやコメントの続きが読めなかったときは problems に入れて止める。"""
    result_items = []
    problems = []
    after = None
    project_id = None
    rate = None
    position = 0
    while True:
        data, problem = graphql("items", {"owner": project["owner"], "number": project["number"], "after": after})
        if problem:
            if not result_items:
                return {"status": "error", **problem}
            problems.append({"what": "items-page", "after": after, **problem})
            break
        node = _project_node(data)
        if node is None:
            return {"status": "error", "failure": "other", "message": f"Project {project['owner']}/{project['number']} が無いか読めない", "exit_code": 0}
