def normalize_path(path):
    """宣言のパス (リポジトリのルートからの相対パス) をそろえる。返り値は (そろえたパス, None) か (None, 問題)。
    posixpath.normpath で `./`・`//`・`a/../` を解き、絶対パス・ルートの外 (`..` で始まる)・ルートそのものを差し戻す。
